use std::{env,fs::{self,File},io::{BufWriter,Write},time::Instant};
fn main(){let args:Vec<_>=env::args().collect();fn get<'a>(a:&'a[String],k:&str)->&'a str{let i=a.iter().position(|x|x==k).unwrap_or_else(||panic!("missing {k}"));&a[i+1]}let method=get(&args,"--method");let l:usize=get(&args,"--l").parse().unwrap();let k:f64=get(&args,"--k").parse().unwrap();let chi:usize=get(&args,"--chi").parse().unwrap();let out=get(&args,"--out");fs::create_dir(out).expect("output must not already exist; create parent directory first");let start=Instant::now();
 if method=="boundary"{let (g,sites,scales,disc)=week10::boundary(l,k,chi);let sec=start.elapsed().as_secs_f64();let mut f=BufWriter::new(File::create(format!("{out}/evidence.json")).unwrap());write!(f,"{{\"method\":\"boundary\",\"geometry\":\"open\",\"L\":{l},\"K\":{k:.17},\"chi\":{chi},\"g\":{g:.17},\"logZ\":{:.17},\"seconds\":{sec:.9},\"log_scales\":{:?},\"discarded_squared\":{:?},\"sites\":[",g*(l*l)as f64,scales,disc).unwrap();for (i,t) in sites.iter().enumerate(){if i>0{write!(f,",").unwrap();}write!(f,"{{\"left\":{},\"right\":{},\"data\":{:?}}}",t.left,t.right,t.data).unwrap();}writeln!(f,"]}}").unwrap();println!("{g:.17} {sec:.9}");}
 else if method=="trg"{let(g,a,steps)=week10::trg(l,k,chi);let sec=start.elapsed().as_secs_f64();let mut f=BufWriter::new(File::create(format!("{out}/evidence.json")).unwrap());write!(f,"{{\"method\":\"trg\",\"geometry\":\"periodic\",\"L\":{l},\"K\":{k:.17},\"chi\":{chi},\"g\":{g:.17},\"logZ\":{:.17},\"seconds\":{sec:.9},\"final_tensor\":{:?},\"steps\":[",g*(l*l)as f64,a).unwrap();for(i,s)in steps.iter().enumerate(){if i>0{write!(f,",").unwrap();}write!(f,"{{\"log_scale\":{},\"old_dim\":{},\"new_dim\":{},\"singular1\":{:?},\"singular2\":{:?},\"factors\":{:?}}}",s.log_scale,s.old_dim,s.new_dim,s.singular1,s.singular2,s.factors).unwrap();}writeln!(f,"]}}").unwrap();println!("{g:.17} {sec:.9}");}else{panic!("unknown method");}}
